package main

import (
	"encoding/json"
	"fmt"
)

type Product struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
	Stock int     `json:"stock,omitempty"`
}

func main() {
	p := Product{ID: 1, Name: "Widget", Price: 9.99, Stock: 100}
	jsonBytes, _ := json.Marshal(p)
	fmt.Println("Encoded:", string(jsonBytes))

	jsonStr := `{"id":2,"name":"Gadget","price":24.99}`
	var decoded Product
	json.Unmarshal([]byte(jsonStr), &decoded)
	fmt.Printf("Decoded: %+v\n", decoded)
}
